  Theorem ax_sound_flush : forall vals R M msF mo (pending : list byte) (code : word),
    length vals = 40%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 2 = code ->
    regs_ok (ENV vals) x_sr R -> know_ok RSEGS (ENV vals) M (ax_kn true true) ->
    (* [comment removed for export] *)
    (bv_unsigned (vals_ev vals 4) - 0x681f00 = Z.of_nat (length pending))%Z ->
    (Z.of_nat (length pending) <= 1024)%Z ->
    rdn RSEGS M (Z_to_bv 64 0x681f00) (length pending) = Some pending ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    (* LPS 75d69e00: the reader premise, in the slot the CALLEE puts it in -- read by step 4a
       from Bo/AsStdioCall.v's own statements at the sha, where `m_channel_reader mo = true`
       sits immediately after the fd_lookup premise and before lzok, in BOTH stdio_call_sound
       (:285-289) and stdio_call_sound_post (:515-517).  Threaded onto the statement and
       discharged by the caller -- this tree's established method, carried the same way by
       Cone's Bo/AsRefused.v:173 and :326, Bo/AsDrvTails and Bo/AsStdioCall -- rather than
       derived from valid_input, which Section Exit does not hold. *)
    m_channel_reader mo = true ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst R (Z_to_bv 64 AEXIT) M (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo) (t_emit (map (WriteEv (Z_to_bv 64 1)) pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs mo))).
