  (* [comment removed for export] *)
  Theorem as_exit_flush : forall regs mem msF mo (sp code we re ro : word) (tid can wp : Z) (pending : list byte),
    axH true mem sp tid can we re ro ->
    rdn RSEGS mem (Z_to_bv 64 0x124008) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 wp)) ->     (* [comment removed for export] *)
    cells_ok mem ax_flush_cells ->                                                          (* [comment removed for export] *)
    (0x681f01 <= wp <= 0x682300)%Z -> (wp - 0x681f00 = Z.of_nat (length pending))%Z ->
    rdn RSEGS mem (Z_to_bv 64 0x681f00) (length pending) = Some pending ->
    getr regs 2 = sp -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 10 = code ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    (* LPS 75d69e00: the channel-reader premise, in the slot the callee [ax_sound_flush]
       puts it in (immediately after fd_lookup, before lzok).  Forwarded, not derived:
       Section Plain holds no [valid_input], so the fact enters from this theorem's own
       caller, exactly as Bo/AsDrvIO.v:57, Bo/AsHdrErr.v:237 and Bo/AsRefused.v:173 carry
       it in this tree. *)
    m_channel_reader mo = true ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst regs (Z_to_bv 64 AEXIT) mem (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo) (t_emit (map (WriteEv (Z_to_bv 64 1)) pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs mo))).
  Proof.
    (* LPS 75d69e00: the recorded proof applied [ax_sound_flush] one argument short of the
       reader premise; written out.  Text from openssl/echconfiglist_parser
       AsExit/AsExit.v:767-786 (as_exit_flush2), which is this shape with an extra [bi]
       case split: the [ax_kn] decomposition, the [kw_var]/[krange_intro] pair and the
       [cells_know] arm are the same.  Every literal below is re-keyed from THIS file's
       own statement -- 0x124008 and 0x681f01/0x682300 from the [Xwp]/[Hwp] premises
       above, 0x681f00 from [RDP] -- never from the donor, whose addresses differ. *)
    intros regs mem msF mo sp code we re ro tid can wp pending
           XH Xwp Xfc Hwp LEN RDP R2 R4 R10 Hfd1 Hrd1 OK RS.
    assert (Z0 : bv_unsigned (Z_to_bv 64 0) = 0%Z) by reflexivity.
    assert (E4 : ev (ENV (x_vals regs sp tid code can wp we re ro)) 4 = Z_to_bv 64 wp) by reflexivity.
    apply (ax_sound_flush sp L S Zr (x_vals regs sp tid code can wp we re ro) regs mem msF mo pending code);
      [ reflexivity | reflexivity | reflexivity | apply x_regs_ok; assumption
      | | cbn [vals_ev x_vals nth app]; rewrite u64_lit by lia; lia
      | lia | exact RDP | exact Hfd1 | exact Hrd1 | exact OK | exact RS ].
    unfold ax_kn. apply (x_know_ok_common true true); [exact XH |].
    apply (proj2 (know_ok_app RSEGS _ _ _ _)).
    split; [| apply cells_know; [vm_compute; reflexivity | exact Xfc]].
    repeat (apply Forall_cons); [ .. | apply Forall_nil ].
    - kw_var Z0 E4 Xwp.
    - apply krange_intro. cbn [edenot]. rewrite E4, u64_lit by lia. lia.
